-- GENERATED by `wfj generate` from data/gossip/gossip-2b.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["2b071faa526eaa9f"] = { "I nostri nemici cadranno!", "." },
  ["2b0e190eea49fbb5"] = { "Eccoti. Che notizie dalle ⟦Westfall=Marche Occidentali⟧?", "." },
  ["2b17593789249847"] = { "Tu, in armonia con la natura, e solo le tue abilità per sopravvivere. Così ha voluto la Madre Terra. Dovrai cercare Bale sull'⟦Hunter Rise=Altura dei Cacciatori⟧.", "." },
  ["2b1c9dbac010e437"] = { "Che cos'è questa storia? Vuoi rovinarmi la reputazione? Io non insegno ai novellini, <bello/bella>. Va' a parlare con ⟦Milla Fairancora=Milla Ferancora⟧ alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus.", "." },
  ["2b1d341d2e1e1202"] = { "<Demitrian ride.>\n\nLa tua ricompensa è una morte rapida e dolorosa, folle!", "." },
  ["2b2297e7493f82cb"] = { "Arrrgh! Non è giusto!", "." },
  ["2b2c91f69bbd5fef"] = { "Che cos'abbiamo qui?", "." },
  ["2b3b2ba5cfbbb50e"] = { "La Madre Terra provvede, ma a volte <un/una> {class} ha bisogno di un piccolo aiuto in più per sopravvivere. Per questo raccolgo tutte le bende di telarunica possibili in preparazione dell'imminente guerra ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Finora ne abbiamo raccolte $2089w, su un totale di $2090w.", "." },
  ["2b409aa9c32305ed"] = { "Quasi tutta la mia compagnia sì. Sfollati quando il terreno ci è crollato sotto i piedi. Alcuni venivano da tutt'altre isole. Io vengo dalla città di Shen'dramar, sulla grande isola. Be', quella che era la grande isola, immagino.\r\n\nLa mia famiglia e io siamo riusciti a salire su uno degli ultimi skycutter prima che l'intera isola andasse in pezzi. Pensavamo che Zephras ci avrebbe salvati. Be', non è stato così. Sono tutti morti da tempo, e ora sono qui, in attesa dell'esecuzione.", "." },
  ["2b47a038c5c0303a"] = { "La ⟦Thorium Brotherhood=Fratellanza del Torio⟧ non perde tempo con le formiche. Vattene!", "." },
  ["2b499141a5edf849"] = { "⟦Grimnur Stonebrand=Grimnur Marcapietra⟧ ti racconterà qualche frottola sul pesce che gli è sfuggito, ma resta uno dei migliori pescatori in circolazione. Ha aperto una bottega nella Caverna degli Inganni, chiamata Traveling Fisherman.", "." },
  ["2b5265fcdd3fc48e"] = { "Be', allora vado. Abbi cura di te, Harlan.", "." },
  ["2b52ce4214d7f49a"] = { "Siamo gli unici fornitori di fiori sani in tutta ⟦Stormwind=Roccavento⟧. Offriamo splendidi fiori per ogni occasione.", "." },
  ["2b5371183e3e2aa7"] = { "Eccellente. Il tuo successo dimostra che sei pront<o/a>.\n\nDi tutti gli elementi, la terra rappresenta il fondamento di tutte le cose. È la tua forza, la tua resistenza e la tua pazienza. La terra ti proteggerà, ma solo se le mostrerai il giusto rispetto. Come gli altri elementi, anche la terra può essere volubile. La terra è la base della vita e, osservandone le leggi, otterrai una saggezza più grande. Non dimenticare mai i segreti che la terra condivide con te.\n\nOra preparerò per te una sapta e, accettandola, comprenderai il tuo sentiero.", "." },
  ["2b54644aeea279af"] = { "Lurido drago! Guardie! Guardie! Prendete questo mostro!", "." },
  ["2b6861fa4f83a9d8"] = { "Tesoran! Mi serve qualcuno, preferibilmente Falgran Hastil, che segua la pista di {name} sulle impronte vicino alla ⟦Shady Rest Inn=Locanda Ombracalma⟧.", "." },
  ["2b70707ef7435e81"] = { "Se solo avessi cinque piedi in più d'altezza, glielo farei vedere io a questi demoni blasfemi! Aiuto!", "." },
  ["2b72d03324436ad6"] = { "Il mio esilio è finito! Che scorra il sangue!", "." },
  ["2b8530a8bdc891a0"] = { "Vanno tutti ai Bastioni ma nessuno torna mai... proprio come Bijou.", "." },
  ["2b8af182d83a029b"] = { "Salve, {class}.", "." },
  ["2b8ca4472986b907"] = { "Cos'è questa storia? Vuoi rovinarmi la reputazione? Io non insegno ai novellini, <amico/bella>. Prova a parlare con l'orco Whuut, nel Drag di Orgrimmar. È molto più vicino al tuo livello di abilità. E di cervello.", "." },
  ["2b9680d953e4fbb5"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare un ⟦Wild Leather Helmet=Elmetto di Cuoio Selvatico⟧?", "." },
  ["2b96c239b7151025"] = { "Dov'è l'anziano Skygleam?", "." },
  ["2b974602ba2ec117"] = { "Ho un sasso nel naso.", "." },
  ["2b9c6b4e1cb0ea44"] = { "%s cade su un ginocchio. Ha l'aria stremata.", "." },
  ["2b9f46faa4a992f1"] = { "Demonio! Affronta la potenza di Cenarius!", "." },
  ["2ba3e61c321e2b71"] = { "Ciao! Andrà meglio la prossima volta!", "." },
  ["2bab0db6023d14c1"] = { "È fatta, {name}, e credo che i risultati ti piaceranno.", "." },
  ["2bb052d907bfa101"] = { "Comprendere l'equilibrio tra la natura e se stessi è uno stile di vita per ogni Elfo della Notte.", "." },
  ["2bb1a8215479bf02"] = { "Gli invasori Kolkar si stanno ritirando!", "." },
  ["2bb27848ba9c69cc"] = { "I racconti delle tue gesta risuonano in tutto il ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧, <maestro/maestra> {name}.", "." },
  ["2bb942d6573c60c6"] = { "C'è un maestro dei pipistrelli dentro ⟦Undercity=Sepulcra⟧. Dirigiti a sud lungo la strada che esce da Brill, poi a ovest all'incrocio a T. Le ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ saranno alla tua sinistra. Entra nelle rovine e poi scendi a ⟦Undercity=Sepulcra⟧. Lì puoi chiedere ulteriore aiuto a un ⟦Undercity Guardian=Guardiano di Sepulcra⟧.", "." },
  ["2bbc984ccc9fa46d"] = { "Ormai sei oltre ciò che so insegnarti, {name}. Va' a importunare ⟦Tally Berryfizz=Tally Frizzabacca⟧: è una gnoma che vive a Tinker Town, a ⟦Ironforge=Forgiardente⟧. Ah, e già che sali, salutami tanto Kali.", "." },
  ["2bc16979818de637"] = { "Chi ha l'auto più veloce? Chi lo sa?!?", "." },
  ["2bc54dcc41dab312"] = { "Mi hai evocato, folle! Ora MUORI!", "." },
  ["2bd0c2d5e1ca8676"] = { "Li respingeremo, ⟦Anachronos=Anacronos⟧. Questo lo giuro. Fa' la tua parte in questo compito. Che le tue mani non vacillino mentre sigilli i nostri destini dietro la barriera.", "." },
  ["2bde102e33bd6dad"] = { "[Dopo la tua domanda c'è una pausa evidente.]\n\nL'informazione richiesta non è al momento disponibile nel ciclo di dati di questo archivio. Mi scuso sinceramente per questa omissione.\n\nRipeti la richiesta dopo che sarà stato eseguito un aggiornamento del ciclo di dati di questo archivio di informazioni. Puoi anche richiedere questa informazione a un altro archivio di informazioni situato su Azeroth.", "." },
  ["2be0c251745720da"] = { "La Bandiera dell'⟦Alliance=Alleanza⟧ è stata presa da {name}!", "." },
  ["2be722a5494c4945"] = { "Il ⟦Iceblood Graveyard=Cimitero di Brinarossa⟧ si trova sul lato sud del ⟦Field of Strife=Pian della Discordia⟧, a est della Torre di Brinarossa.\n\nAl momento non è controllato da nessuna delle due fazioni.", "." },
  ["2bed231a8c8a1ca9"] = { "Oh, eccoti!", "." },
  ["2bee2e3cafd6773a"] = { "Sta' giù, miserabile!", "." },
  ["2bf4530ada571b45"] = { "%s scruta il mulino", "." },
  ["2bfdc52597a635a5"] = { "Salute, {class}, posso insegnarti abilità e tecniche.", "." },
})
